<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Database\Connection;
use App\Helpers\Input;
use App\Helpers\Response;
use App\Services\AuditService;
final class DataController {
    public static function schools(array $user): never { $s=Connection::get()->query('SELECT * FROM escolas ORDER BY nome');Response::send($s->fetchAll()); }
    public static function routes(array $user): never { $s=Connection::get()->query('SELECT r.*,t.nome AS turno_nome,e.nome AS escola_nome FROM rotas r LEFT JOIN turnos t ON t.id=r.turno_id LEFT JOIN escolas e ON e.id=r.escola_id ORDER BY r.nome');Response::send($s->fetchAll()); }
    public static function vehicles(array $user): never { $s=Connection::get()->query('SELECT * FROM veiculos ORDER BY placa');Response::send($s->fetchAll()); }
    public static function trips(array $user): never { $date=$_GET['data']??date('Y-m-d');$s=Connection::get()->prepare('SELECT v.*,r.codigo AS rota_codigo,r.nome AS rota_nome,ve.placa,m.nome AS motorista_nome,mo.nome AS monitor_nome FROM viagens v JOIN rotas r ON r.id=v.rota_id LEFT JOIN veiculos ve ON ve.id=v.veiculo_id LEFT JOIN motoristas mt ON mt.id=v.motorista_id LEFT JOIN usuarios m ON m.id=mt.usuario_id LEFT JOIN monitores mn ON mn.id=v.monitor_id LEFT JOIN usuarios mo ON mo.id=mn.usuario_id WHERE v.data_viagem=:date ORDER BY v.id');$s->execute(['date'=>$date]);Response::send($s->fetchAll()); }
    public static function students(array $user): never { $where='';$params=[];if($user['perfil']==='RESPONSÁVEL'){$where='AND ar.responsavel_id=(SELECT id FROM responsaveis WHERE usuario_id=:uid)';$params['uid']=$user['id'];}$search=trim((string)($_GET['q']??''));if($search!==''){$where.=' AND (a.nome ILIKE :q OR a.cpf LIKE :cpf)';$params['q']='%'.$search.'%';$params['cpf']='%'.preg_replace('/\D+/','',$search).'%';}$s=Connection::get()->prepare("SELECT a.id,a.nome,a.cpf,a.data_nascimento,a.pne,a.status,e.nome AS escola_nome,ae.turno,r.nome AS responsavel_nome,en.logradouro,en.numero,en.bairro,en.cidade,en.uf,en.cep,ro.nome AS rota_nome FROM alunos a LEFT JOIN aluno_escola ae ON ae.aluno_id=a.id AND ae.ano_letivo=(SELECT ano FROM anos_letivos WHERE ativo=true ORDER BY ano DESC LIMIT 1) LEFT JOIN escolas e ON e.id=ae.escola_id LEFT JOIN aluno_responsavel ar ON ar.aluno_id=a.id AND ar.principal=true LEFT JOIN responsaveis r ON r.id=ar.responsavel_id LEFT JOIN enderecos en ON en.id=a.endereco_id LEFT JOIN rota_alunos ra ON ra.aluno_escola_id=ae.id AND ra.ativo=true LEFT JOIN rotas ro ON ro.id=ra.rota_id WHERE 1=1 {$where} ORDER BY a.nome");$s->execute($params);Response::send($s->fetchAll()); }
    public static function createSchool(array $user): never { AuthGate::adminOrOperator($user);$d=Input::json();$code=Input::string($d,'codigo_inep');$name=Input::string($d,'nome',true);$log=Input::string($d,'logradouro');$num=Input::string($d,'numero');$bairro=Input::string($d,'bairro');$cep=Input::string($d,'cep');$lat=$d['latitude']??null;$lon=$d['longitude']??null;if($code!==null){$q=Connection::get()->prepare('SELECT id FROM escolas WHERE codigo_inep=:code');$q->execute(['code'=>$code]);if($q->fetchColumn()!==false)Response::error('Já existe uma escola com este código INEP.',422);} $s=Connection::get()->prepare('INSERT INTO escolas (codigo_inep,nome,logradouro,numero,bairro,cep,latitude,longitude,ativo) VALUES (:inep,:name,:log,:num,:bairro,:cep,:lat,:lon,true) RETURNING id');$s->execute(['inep'=>$code,'name'=>$name,'log'=>$log,'num'=>$num,'bairro'=>$bairro,'cep'=>$cep,'lat'=>$lat===''?null:$lat,'lon'=>$lon===''?null:$lon]);$id=(int)$s->fetchColumn();AuditService::record((int)$user['id'],$user['perfil'],'CADASTRO','ESCOLAS','escolas',$id,'Escola cadastrada.',null,$d);Response::send(['id'=>$id],201);}
    public static function updateSchool(array $user,int $id): never { AuthGate::adminOrOperator($user);$d=Input::json();$q=Connection::get()->prepare('SELECT * FROM escolas WHERE id=:id');$q->execute(['id'=>$id]);$before=$q->fetch();if(!$before)Response::error('Escola não encontrada.',404);$code=array_key_exists('codigo_inep',$d)?Input::string($d,'codigo_inep'):$before['codigo_inep'];$name=array_key_exists('nome',$d)?Input::string($d,'nome',true):$before['nome'];$log=array_key_exists('logradouro',$d)?Input::string($d,'logradouro'):$before['logradouro'];$num=array_key_exists('numero',$d)?Input::string($d,'numero'):$before['numero'];$bairro=array_key_exists('bairro',$d)?Input::string($d,'bairro'):$before['bairro'];$cep=array_key_exists('cep',$d)?Input::string($d,'cep'):$before['cep'];$lat=array_key_exists('latitude',$d)?$d['latitude']:$before['latitude'];$lon=array_key_exists('longitude',$d)?$d['longitude']:$before['longitude'];if($code!==null){$q=Connection::get()->prepare('SELECT id FROM escolas WHERE codigo_inep=:code AND id<>:id');$q->execute(['code'=>$code,'id'=>$id]);if($q->fetchColumn()!==false)Response::error('Já existe outra escola com este código INEP.',422);} $q=Connection::get()->prepare('UPDATE escolas SET codigo_inep=:inep,nome=:name,logradouro=:log,numero=:num,bairro=:bairro,cep=:cep,latitude=:lat,longitude=:lon WHERE id=:id');$q->execute(['inep'=>$code,'name'=>$name,'log'=>$log,'num'=>$num,'bairro'=>$bairro,'cep'=>$cep,'lat'=>$lat===''?null:$lat,'lon'=>$lon===''?null:$lon,'id'=>$id]);$q=Connection::get()->prepare('SELECT * FROM escolas WHERE id=:id');$q->execute(['id'=>$id]);$after=$q->fetch();AuditService::record((int)$user['id'],$user['perfil'],'ALTERACAO','ESCOLAS','escolas',$id,'Escola alterada.',$before,$after);Response::send($after);}
    public static function setSchoolStatus(array $user,int $id): never { AuthGate::adminOrOperator($user);$d=Input::json();if(!array_key_exists('ativo',$d))Response::error('Informe o status da escola.',422);$ativo=filter_var($d['ativo'],FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($ativo===null)Response::error('O status informado é inválido.',422);$q=Connection::get()->prepare('SELECT * FROM escolas WHERE id=:id');$q->execute(['id'=>$id]);$before=$q->fetch();if(!$before)Response::error('Escola não encontrada.',404);$q=Connection::get()->prepare('UPDATE escolas SET ativo=:ativo WHERE id=:id');$q->execute(['ativo'=>$ativo,'id'=>$id]);$q=Connection::get()->prepare('SELECT * FROM escolas WHERE id=:id');$q->execute(['id'=>$id]);$after=$q->fetch();$action=$ativo?'REATIVACAO':'INATIVACAO';AuditService::record((int)$user['id'],$user['perfil'],$action,'ESCOLAS','escolas',$id,$ativo?'Escola reativada.':'Escola inativada.',$before,$after);Response::send($after);}
    public static function operationalAction(array $user,string $kind): never { if(!in_array($user['perfil'],['ADMINISTRADOR','OPERADOR','MOTORISTA','MONITOR'],true))Response::error('Você não possui permissão para esta operação.',403);$d=Input::json();$map=['embarques'=>['table'=>'embarques','fields'=>['viagem_id','aluno_id','latitude','longitude','observacao']],'desembarques'=>['table'=>'desembarques','fields'=>['viagem_id','aluno_id','latitude','longitude','autorizado_por_responsavel','observacao']],'ocorrencias'=>['table'=>'ocorrencias','fields'=>['viagem_id','aluno_id','tipo','descricao','gravidade']]];if(!isset($map[$kind]))Response::error('Operação não encontrada.',404);$cfg=$map[$kind];if(empty($d['viagem_id'])||empty($d['aluno_id']))Response::error('Viagem e aluno são obrigatórios.',422);if($kind==='ocorrencias'){if(empty($d['tipo'])||empty($d['descricao']))Response::error('Tipo e descrição são obrigatórios.',422);$s=Connection::get()->prepare('INSERT INTO ocorrencias (viagem_id,aluno_id,registrado_por,tipo,descricao,gravidade) VALUES (:viagem,:aluno,:user,:tipo,:desc,:gravidade) RETURNING id');$s->execute(['viagem'=>$d['viagem_id'],'aluno'=>$d['aluno_id'],'user'=>$user['id'],'tipo'=>$d['tipo'],'desc'=>$d['descricao'],'gravidade'=>$d['gravidade']??'NORMAL']);$id=(int)$s->fetchColumn();}else{$table=$cfg['table'];$sql=$table==='embarques'?'INSERT INTO embarques (viagem_id,aluno_id,registrado_por,latitude,longitude,observacao) VALUES (:viagem,:aluno,:user,:lat,:lon,:obs) ON CONFLICT (viagem_id,aluno_id) DO UPDATE SET registrado_por=EXCLUDED.registrado_por,registrado_em=NOW(),latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,observacao=EXCLUDED.observacao RETURNING id':'INSERT INTO desembarques (viagem_id,aluno_id,registrado_por,latitude,longitude,autorizado_por_responsavel,observacao) VALUES (:viagem,:aluno,:user,:lat,:lon,:autorizado,:obs) ON CONFLICT (viagem_id,aluno_id) DO UPDATE SET registrado_por=EXCLUDED.registrado_por,registrado_em=NOW(),latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,autorizado_por_responsavel=EXCLUDED.autorizado_por_responsavel,observacao=EXCLUDED.observacao RETURNING id';$s=Connection::get()->prepare($sql);$s->execute(['viagem'=>$d['viagem_id'],'aluno'=>$d['aluno_id'],'user'=>$user['id'],'lat'=>$d['latitude']??null,'lon'=>$d['longitude']??null,'autorizado'=>$d['autorizado_por_responsavel']??null,'obs'=>$d['observacao']??null]);$id=(int)$s->fetchColumn();}$action=strtoupper($kind);AuditService::record((int)$user['id'],$user['perfil'],$action,'OPERACAO',$kind,$id,'Registro operacional realizado.',null,$d);Response::send(['id'=>$id],201); }
    public static function createRoute(array $user): never { AuthGate::adminOrOperator($user); $d=Input::json(); if(trim((string)($d['codigo']??''))===''||trim((string)($d['nome']??''))==='')Response::error('Código e nome da rota são obrigatórios.',422); $s=Connection::get()->prepare('INSERT INTO rotas (codigo,nome,descricao,turno_id,escola_id,ativo) VALUES (:codigo,:nome,:descricao,:turno,:escola,true) RETURNING id'); $s->execute(['codigo'=>trim((string)$d['codigo']),'nome'=>trim((string)$d['nome']),'descricao'=>$d['descricao']??null,'turno'=>$d['turno_id']??null,'escola'=>$d['escola_id']??null]); $id=(int)$s->fetchColumn(); AuditService::record((int)$user['id'],$user['perfil'],'CADASTRO','ROTAS','rotas',$id,'Rota cadastrada.',null,$d); Response::send(['id'=>$id],201); }
    public static function createVehicle(array $user): never { AuthGate::adminOrOperator($user); $d=Input::json(); if(trim((string)($d['placa']??''))==='')Response::error('A placa é obrigatória.',422); $s=Connection::get()->prepare('INSERT INTO veiculos (placa,renavam,modelo,fabricante,ano_fabricacao,capacidade,acessibilidade,ativo) VALUES (:placa,:renavam,:modelo,:fabricante,:ano,:capacidade,:acessibilidade,true) RETURNING id'); $s->execute(['placa'=>mb_strtoupper(trim((string)$d['placa']),'UTF-8'),'renavam'=>$d['renavam']??null,'modelo'=>$d['modelo']??null,'fabricante'=>$d['fabricante']??null,'ano'=>$d['ano_fabricacao']??null,'capacidade'=>$d['capacidade']??null,'acessibilidade'=>(bool)($d['acessibilidade']??false)]); $id=(int)$s->fetchColumn(); AuditService::record((int)$user['id'],$user['perfil'],'CADASTRO','VEICULOS','veiculos',$id,'Veículo cadastrado.',null,$d); Response::send(['id'=>$id],201); }
    public static function notices(array $user): never { $s=Connection::get()->prepare('SELECT a.*,ad.visualizado_em,ad.reconhecido_em FROM avisos a JOIN aviso_destinatarios ad ON ad.aviso_id=a.id WHERE ad.usuario_id=:uid AND a.ativo=true AND (a.inicio_em IS NULL OR a.inicio_em<=NOW()) AND (a.fim_em IS NULL OR a.fim_em>=NOW()) ORDER BY a.bloqueante DESC,a.criado_em DESC');$s->execute(['uid'=>$user['id']]);Response::send($s->fetchAll()); }
    public static function createNotice(array $user): never { AuthGate::adminOrOperator($user);$d=Input::json();if(trim((string)($d['titulo']??''))===''||trim((string)($d['mensagem']??''))==='')Response::error('Título e mensagem são obrigatórios.',422);$db=Connection::get();$db->beginTransaction();try{$s=$db->prepare('INSERT INTO avisos (titulo,mensagem,prioridade,modulo,entidade,entidade_id,bloqueante,criado_por) VALUES (:titulo,:mensagem,:prioridade,:modulo,:entidade,:entidade_id,:bloqueante,:user) RETURNING id');$s->execute(['titulo'=>$d['titulo'],'mensagem'=>$d['mensagem'],'prioridade'=>$d['prioridade']??'NORMAL','modulo'=>$d['modulo']??null,'entidade'=>$d['entidade']??null,'entidade_id'=>$d['entidade_id']??null,'bloqueante'=>(bool)($d['bloqueante']??false),'user'=>$user['id']]);$id=(int)$s->fetchColumn();$targets=$d['usuarios']??[];if(!$targets){$targets=$db->query('SELECT id FROM usuarios WHERE ativo=true')->fetchAll(\PDO::FETCH_COLUMN);}foreach($targets as $uid)$db->prepare('INSERT INTO aviso_destinatarios (aviso_id,usuario_id) VALUES (:aid,:uid) ON CONFLICT DO NOTHING')->execute(['aid'=>$id,'uid'=>$uid]);$db->commit();AuditService::record((int)$user['id'],$user['perfil'],'CADASTRO','AVISOS','avisos',$id,'Aviso criado.',null,$d);Response::send(['id'=>$id],201);}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}

    public static function student(array $user,int $id): never { $sql="SELECT a.*,e.nome AS escola_nome,ae.ano_letivo,ae.turno,ae.autorizacao_desembarque,ae.distancia_calculada_m,ae.distancia_caminhada_m,r.nome AS responsavel_nome,r.email AS responsavel_email,r.telefone AS responsavel_telefone,en.logradouro,en.numero,en.bairro,en.cidade,en.uf,en.cep,en.latitude,en.longitude,ro.nome AS rota_nome FROM alunos a LEFT JOIN aluno_escola ae ON ae.aluno_id=a.id AND ae.ano_letivo=(SELECT ano FROM anos_letivos WHERE ativo=true ORDER BY ano DESC LIMIT 1) LEFT JOIN escolas e ON e.id=ae.escola_id LEFT JOIN aluno_responsavel ar ON ar.aluno_id=a.id AND ar.principal=true LEFT JOIN responsaveis r ON r.id=ar.responsavel_id LEFT JOIN enderecos en ON en.id=a.endereco_id LEFT JOIN rota_alunos ra ON ra.aluno_escola_id=ae.id AND ra.ativo=true LEFT JOIN rotas ro ON ro.id=ra.rota_id WHERE a.id=:id";$s=Connection::get()->prepare($sql);$s->execute(['id'=>$id]);$row=$s->fetch();if(!$row)Response::error('Aluno não encontrado.',404);if($user['perfil']==='RESPONSÁVEL'){ $q=Connection::get()->prepare('SELECT 1 FROM aluno_responsavel ar JOIN responsaveis r ON r.id=ar.responsavel_id WHERE ar.aluno_id=:aid AND r.usuario_id=:uid');$q->execute(['aid'=>$id,'uid'=>$user['id']]);if(!$q->fetch())Response::error('Você não possui acesso a este aluno.',403);}Response::send($row); }
    public static function updateStudent(array $user,int $id): never { AuthGate::adminOrOperator($user);$d=Input::json();$s=Connection::get()->prepare('SELECT * FROM alunos WHERE id=:id');$s->execute(['id'=>$id]);$before=$s->fetch();if(!$before)Response::error('Aluno não encontrado.',404);$allowed=['nome','data_nascimento','pne','tipo_pne_cid','status'];$set=[];$params=['id'=>$id];foreach($allowed as $field)if(array_key_exists($field,$d)){$set[]=$field.'=:'.$field;$params[$field]=$d[$field];}if(!$set)Response::error('Nenhuma alteração foi informada.',422);$set[]='atualizado_em=NOW()';$q=Connection::get()->prepare('UPDATE alunos SET '.implode(',',$set).' WHERE id=:id');$q->execute($params);$q=Connection::get()->prepare('SELECT * FROM alunos WHERE id=:id');$q->execute(['id'=>$id]);$after=$q->fetch();AuditService::record((int)$user['id'],$user['perfil'],'ALTERACAO','ALUNOS','alunos',$id,'Aluno alterado.',$before,$after);Response::send($after); }
    public static function createTrip(array $user): never { AuthGate::adminOrOperator($user);$d=Input::json();foreach(['rota_id','ano_letivo','data_viagem'] as $f)if(empty($d[$f]))Response::error('Informe rota, ano letivo e data da viagem.',422);$s=Connection::get()->prepare('INSERT INTO viagens (rota_id,veiculo_id,motorista_id,monitor_id,ano_letivo,data_viagem,tipo,status) VALUES (:rota,:veiculo,:motorista,:monitor,:ano,:data,:tipo,\'PLANEJADA\') RETURNING id');$s->execute(['rota'=>$d['rota_id'],'veiculo'=>$d['veiculo_id']??null,'motorista'=>$d['motorista_id']??null,'monitor'=>$d['monitor_id']??null,'ano'=>$d['ano_letivo'],'data'=>$d['data_viagem'],'tipo'=>$d['tipo']??'IDA']);$id=(int)$s->fetchColumn();AuditService::record((int)$user['id'],$user['perfil'],'CADASTRO','VIAGENS','viagens',$id,'Viagem planejada.',null,$d);Response::send(['id'=>$id],201); }
    public static function checklist(array $user,int $tripId): never { if(!in_array($user['perfil'],['ADMINISTRADOR','OPERADOR','MOTORISTA'],true))Response::error('Você não possui permissão.',403);$d=Input::json();$s=Connection::get()->prepare('SELECT id FROM motoristas WHERE usuario_id=:uid');$s->execute(['uid'=>$user['id']]);$driver=$s->fetchColumn();if($user['perfil']==='MOTORISTA'&&!$driver)Response::error('Usuário não está vinculado a um motorista.',403);$driver=$d['motorista_id']??$driver;if(!$driver)Response::error('Informe o motorista.',422);$q=Connection::get()->prepare('INSERT INTO checklists_veiculo (viagem_id,motorista_id,itens,observacoes,resultado) VALUES (:trip,:driver,:items,:obs,:result) RETURNING id');$q->execute(['trip'=>$tripId,'driver'=>$driver,'items'=>json_encode($d['itens']??[],JSON_UNESCAPED_UNICODE),'obs'=>$d['observacoes']??null,'result'=>$d['resultado']??'APROVADO']);$id=(int)$q->fetchColumn();AuditService::record((int)$user['id'],$user['perfil'],'REGISTRO_CHECKLIST','VIAGENS','checklists_veiculo',$id,'Checklist registrado.',null,$d);Response::send(['id'=>$id],201); }
    public static function maintenance(array $user): never { if(!in_array($user['perfil'],['ADMINISTRADOR','OPERADOR','MOTORISTA'],true))Response::error('Você não possui permissão.',403);$d=Input::json();foreach(['veiculo_id','tipo','descricao'] as $f)if(empty($d[$f]))Response::error('Veículo, tipo e descrição são obrigatórios.',422);$q=Connection::get()->prepare('INSERT INTO manutencoes (veiculo_id,registrado_por,tipo,descricao,quilometragem,data_manutencao,proxima_manutencao,status) VALUES (:vehicle,:user,:type,:desc,:km,COALESCE(:date,CURRENT_DATE),:next,:status) RETURNING id');$q->execute(['vehicle'=>$d['veiculo_id'],'user'=>$user['id'],'type'=>$d['tipo'],'desc'=>$d['descricao'],'km'=>$d['quilometragem']??null,'date'=>$d['data_manutencao']??null,'next'=>$d['proxima_manutencao']??null,'status'=>$d['status']??'ABERTA']);$id=(int)$q->fetchColumn();AuditService::record((int)$user['id'],$user['perfil'],'REGISTRO_MANUTENCAO','MANUTENCAO','manutencoes',$id,'Manutenção registrada.',null,$d);Response::send(['id'=>$id],201); }

}
